}

{
  "id": 59,
  "knowledge": "Systemically Stressed Facility Environment",
  "description": "Identifies facilities potentially facing overwhelming systemic stress, characterized by a significant gap between patient needs and resources, compounded by high patient attrition risk.",
  "definition": "A facility where RDD > 1.0 AND meeting criteria for Facility Attrition Risk Indicator. \\text{Combines a high Resource-Demand Differential (RDD) with indicators of high attrition risk.}"
}

{
  "id": 23,
  "knowledge": "Therapy Engagement",
  "description": "Illustrates the value of therapy engagement levels.",
  "definition": "Ranges from Non-compliant to High. Non-compliant indicates no participation, Low indicates minimal participation, Medium indicates regular participation, and High indicates active engagement."
}

{
  "id": 30,
  "knowledge": "Symptom Severity Index (SSI)",
  "description": "Calculates a combined average symptom severity score for a facility, based on depression and anxiety.",
  "definition": "SSI = \\frac{APSF + AGSF}{2}, \\text{using Average PHQ-9 Score (APSF) and Average GAD-7 Score (AGSF)}"
}

{
  "id": 34,
  "knowledge": "Resource-Demand Differential (RDD)",
  "description": "Measures the potential gap between average patient functional needs and available facility resources.",
  "definition": "RDD = PFIS - FRAI, \\text{comparing Patient Functional Impairment Score (PFIS) to Facility Resource Adequacy Index (FRAI)}"
}

{
  "id": 43,
  "knowledge": "Facility Attrition Risk Indicator",
  "description": "Identifies facilities potentially experiencing high patient dropout, characterized by low engagement/adherence and high missed appointment rates.",
  "definition": "A facility where EAS < 1.5 and MAR > 2.5, \\text{based on low Engagement-Adherence Score (EAS) and high Missed Appointment Rate (MAR)}"
}

{
  "id": 14,
  "knowledge": "Low Engagement Risk",
  "description": "Identifies patients at risk of disengagement from therapy.",
  "definition": "A patient with TES < 1.5 and txeng \\in \\{Low, Non-compliant\\}"
}

{
  "id": 37,
  "knowledge": "Engagement Deficit Index (EDI)",
  "description": "Quantifies the degree of patient disengagement, considering both therapy engagement scores and appointment attendance.",
  "definition": "EDI = (3 - TES) \\times (1 + MAR), \\text{calculating the gap from maximum Therapy Engagement Score (TES) weighted by Missed Appointment Rate (MAR)}"
}

{
  "id": 52,
  "knowledge": "Therapeutic Alliance & Engagement Score (TAES)",
  "description": "Computes a combined score reflecting both the average clinician-reported therapeutic alliance and the calculated therapy engagement score for a facility.",
  "definition": "TAES = \\frac{Average(theralliance\\_score) + TES}{2}, \\text{where } theralliance\\_score = \\begin{cases} 3 & \\text{if } theralliance = Strong \\\\ 2 & \\text{if } theralliance = Moderate \\\\ 1 & \\text{if } theralliance = Weak \\\\ 0 & \\text{if } theralliance = Poor \\end{cases}, \\text{averaged across treatmentoutcomes, combined with Therapy Engagement Score (TES)}."
}

{
  "id": 31,
  "knowledge": "Engagement-Adherence Score (EAS)",
  "description": "Computes a composite score reflecting patient participation and adherence to treatment plans at a facility.",
  "definition": "EAS = \\frac{TES + (TAR \\times 3)}{2}, \\text{normalizing Treatment Adherence Rate (TAR) to the Therapy Engagement Score (TES) scale (0-3)}"
}

{
  "id": 6,
  "knowledge": "Patient Functional Impairment Score (PFIS)",
  "description": "Calculates an average functional impairment score across patients.",
  "definition": "PFIS = \\frac{\\sum_{i \\in assessmentsocialanddiagnosis} funcimp\\_score_i} {|assessmentsocialanddiagnosis|}, \\text{where } funcimp\\_score = \\begin{cases} 3 & \\text{if } funcimp = Severe \\\\ 2 & \\text{if } funcimp = Moderate \\\\ 1 & \\text{if } funcimp = Mild \\end{cases}"
}

{
  "id": 5,
  "knowledge": "Facility Resource Adequacy Index (FRAI)",
  "description": "Quantifies the adequacy of community resources available at a facility.",
  "definition": "FRAI = \\frac{\\sum_{i \\in facilities} resource\\_score_i} {|facilities|}, \\text{where } resource\\_score = \\begin{cases} 3 & \\text{if } support\\_and\\_resources['community\\_resources'] = Comprehensive \\\\ 2 & \\text{if } support\\_and\\_resources['community\\_resources'] = Adequate \\\\ 1 & \\text{if } support\\_and\\_resources['community\\_resources'] = Limited \\end{cases}, \\text{and } support\\_and\\_resources \\text{ is the JSONB column in the facilities table}"
}

{
  "id": 9,
  "knowledge": "Missed Appointment Rate (MAR)",
  "description": "Calculates the average number of missed appointments per patient at a facility.",
  "definition": "MAR = \\frac{\\sum_{i \\in encounters} missappt_i} {|patients|}"
}

{
  "id": 2,
  "knowledge": "Treatment Adherence Rate (TAR)",
  "description": "Measures the proportion of patients with high or medium treatment adherence at a facility.",
  "definition": "TAR = \\frac{|treatmentoutcomes \\text{ with } txadh \\in \\{High, Medium\\}|} {|treatmentoutcomes|}"
}

{
  "id": 26,
  "knowledge": "Treatment Adherence",
  "description": "Illustrates the value of treatment adherence levels.",
  "definition": "Ranges from Non-compliant to High. Non-compliant indicates no adherence, Low indicates occasional adherence, Medium indicates regular adherence, and High indicates consistent adherence."
}

{
  "id": 0,
  "knowledge": "Average PHQ-9 Score by Facility (APSF)",
  "description": "Calculates the average PHQ-9 depression score for patients assessed at a specific facility.",
  "definition": "APSF = \\frac{\\sum_{i \\in assessmentsymptomsandrisk} (mental\\_health\\_scores_i['depression']['phq9\\_score'])} {|assessmentsymptomsandrisk|}"
}

{
  "id": 1,
  "knowledge": "Average GAD-7 Score by Facility (AGSF)",
  "description": "Calculates the average GAD-7 anxiety score for patients assessed at a specific facility.",
  "definition": "AGSF = \\frac{\\sum_{i \\in assessmentsymptomsandrisk} (mental\\_health\\_scores_i['anxiety']['gad7\\_score'])} {|assessmentsymptomsandrisk|}, \\text{where } mental\\_health\\_scores_i['anxiety']['gad7\\_score'] \\text{ is the GAD-7 score for each assessment in the assessmentsymptomsandrisk table, linked to a facility via encounters.facid}"
}

{
  "id": 38,
  "knowledge": "Comprehensive Facility Risk Score (CFRS)",
  "description": "A normalized index assessing overall facility risk based on combined depression severity, suicide risk prevalence, and functional impairment.",
  "definition": "CFRS = \\frac{APSF}{27} + \\frac{SRP}{100} + \\frac{PFIS}{3}, \\text{normalizing Average PHQ-9 Score (APSF), Suicide Risk Prevalence (SRP), and Patient Functional Impairment Score (PFIS) to a 0-1 scale and summing}"
}

